import{_ as s,C as r,o as t,c as l,j as i,a,b as d,w as n,E as c,a6 as p,a2 as g}from"./chunks/framework.CAzL99r7.js";const b=JSON.parse('{"title":"Telematics Engine & Signal Processing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/signal-processing.md","filePath":"guide/signal-processing.md"}'),m={name:"guide/signal-processing.md"};function h(u,e,v,S,f,y){const o=r("Mermaid");return t(),l("div",null,[e[1]||(e[1]=i("h1",{id:"telematics-engine-signal-processing",tabindex:"-1"},[a("Telematics Engine & Signal Processing "),i("a",{class:"header-anchor",href:"#telematics-engine-signal-processing","aria-label":'Permalink to "Telematics Engine & Signal Processing"'},"​")],-1)),e[2]||(e[2]=i("p",null,[a("The core telematics pipeline in "),i("code",null,":speed-core"),a(" ("),i("code",null,"TelematicsEngine.kt"),a(") and the compiled native engine process raw GPS fixes through mathematical smoothing and deterministic boundary checks to eliminate false alarms and jitter.")],-1)),e[3]||(e[3]=i("hr",null,null,-1)),e[4]||(e[4]=i("h2",{id:"mathematical-signal-pipeline",tabindex:"-1"},[a("Mathematical Signal Pipeline "),i("a",{class:"header-anchor",href:"#mathematical-signal-pipeline","aria-label":'Permalink to "Mathematical Signal Pipeline"'},"​")],-1)),e[5]||(e[5]=i("p",null,"Raw GPS sensor hardware suffers from multipath reflections, satellite geometry variance, and momentary signal noise. The telematics pipeline filters raw velocity through three sequential mathematical stages:",-1)),(t(),d(p,null,{default:n(()=>[c(o,{id:"mermaid-13",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5B%22Raw%20GPS%20Fix%20(Speed%20%26%20Accuracy)%22%5D%20--%3E%20B%7B%22Horizontal%20Accuracy%20Gating%22%7D%0A%20%20%20%20B%20--%3E%7CExceeds%20Uncertainty%20Limit%7C%20C%5B%22Emit%20LowAccuracy%20State%22%5D%0A%20%20%20%20B%20--%3E%7CHigh%20Confidence%20GPS%20Fix%7C%20D%5B%22Native%20C%2B%2B%20EMA%20Smoothing%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22Smoothed%20Velocity%20Stream%22%5D%0A%20%20%20%20E%20--%3E%20F%7B%22Dynamic%20Threshold%20Evaluation%22%7D%0A%20%20%20%20F%20--%3E%7CSmoothed%20Speed%20%3E%20Limit%7C%20G%5B%22Trigger%20Over-Speed%20Alert%22%5D%0A%20%20%20%20F%20--%3E%7CSmoothed%20Speed%20%3C%3D%20Limit%7C%20H%5B%22Maintain%20Safe%20Cruising%20State%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=g('<hr><h2 id="_1-gps-confidence-accuracy-gating" tabindex="-1">1. GPS Confidence &amp; Accuracy Gating <a class="header-anchor" href="#_1-gps-confidence-accuracy-gating" aria-label="Permalink to &quot;1. GPS Confidence &amp; Accuracy Gating&quot;">​</a></h2><p>Before any velocity reading is processed, <code>TelematicsEngine</code> validates the horizontal accuracy estimate (2σ precision in meters):</p><div class="tip custom-block"><p class="custom-block-title">Confidence Validation Gate</p><p>A raw GPS fix is accepted only when:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>horizontalAccuracy &lt;= CONFIDENCE_THRESHOLD (20.0 meters, 2σ confidence)</span></span></code></pre></div><p>If the device reports poor satellite geometry (e.g. inside tunnels or urban canyons where accuracy exceeds the threshold), the fix is discarded and the SDK emits <code>SpeedData.LowAccuracy</code>. This prevents inaccurate velocity spikes from sounding alarms.</p></div><hr><h2 id="_2-native-exponential-moving-average-ema-smoothing" tabindex="-1">2. Native Exponential Moving Average (EMA) Smoothing <a class="header-anchor" href="#_2-native-exponential-moving-average-ema-smoothing" aria-label="Permalink to &quot;2. Native Exponential Moving Average (EMA) Smoothing&quot;">​</a></h2><p>To eliminate erratic velocity jitter from raw GPS sensor readings, the engine applies discrete first-order Exponential Moving Average (EMA) smoothing:</p><div class="tip custom-block"><p class="custom-block-title">Discrete EMA Equation</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SmoothedVelocity[t] = α · RawVelocity[t] + (1 - α) · SmoothedVelocity[t - 1]</span></span></code></pre></div><p>Where <strong>α (alpha)</strong> is a proprietary smoothing coefficient calibrated for optimal balance between gauge responsiveness and jitter suppression. The smoothing calculation is securely executed inside the compiled native engine with zero start-of-trip lag.</p></div><hr><h2 id="_3-dynamic-speed-limit-thresholding-safety-logic" tabindex="-1">3. Dynamic Speed Limit Thresholding &amp; Safety Logic <a class="header-anchor" href="#_3-dynamic-speed-limit-thresholding-safety-logic" aria-label="Permalink to &quot;3. Dynamic Speed Limit Thresholding &amp; Safety Logic&quot;">​</a></h2><p>Speed alerts are dynamically evaluated against the active <code>DrivingProfile</code>:</p><ul><li><strong>Over-Speed Alert:</strong> When smoothed velocity exceeds the profile&#39;s legal ceiling (<code>smoothedSpeed &gt; warningThresholdMps</code>), <code>isOverLimit = true</code> is immediately emitted.</li><li><strong>Under-Speed Corridor Warning:</strong> When a minimum speed corridor is configured and speed drops below the corridor floor (<code>smoothedSpeed &lt; minWarningThresholdMps</code>), <code>isUnderLimit = true</code> is emitted.</li><li><strong>Stationary Suppression:</strong> To prevent false under-speed warnings during stoplights, traffic, or crawling stops, under-speed alerts are automatically silenced during stop-and-go conditions until the vehicle accelerates into motion.</li><li><strong>Instantaneous Boundary Response:</strong> Pre-filtering raw sensor noise via native EMA smoothing removes the need for artificial hysteresis dismissal delays (such as holding alarms until decelerating by -3 km/h below the limit). Alarms dismiss immediately once the driver returns within the legal speed window, eliminating confusing audio chatter and avoiding unfair penalties to driver Mindful Driving Scores.</li></ul><hr><h2 id="non-standard-vehicle-advanced-applications" tabindex="-1">Non-Standard Vehicle &amp; Advanced Applications <a class="header-anchor" href="#non-standard-vehicle-advanced-applications" aria-label="Permalink to &quot;Non-Standard Vehicle &amp; Advanced Applications&quot;">​</a></h2><p>Because <code>TelematicsEngine</code> is pure Kotlin and decoupled from Android UI, it can be applied to non-automotive telematics domains:</p><h3 id="_1-consumer-drones-uavs" tabindex="-1">1. Consumer Drones (UAVs) <a class="header-anchor" href="#_1-consumer-drones-uavs" aria-label="Permalink to &quot;1. Consumer Drones (UAVs)&quot;">​</a></h3><ul><li><strong>Use Case:</strong> Regulations cap drone speeds (e.g., <strong>100 mph</strong> in the US).</li><li><strong>Application:</strong> Drone ground control apps running on Android can pipe UAV telemetry directly into <code>TelematicsEngine</code> using <code>SpeedUnit.MILES_PER_HOUR</code> or <code>SpeedUnit.METERS_PER_SECOND</code> to warn pilots if wind currents push the drone past legal airspeed.</li></ul><h3 id="_2-maritime-marine-boats-jet-skis" tabindex="-1">2. Maritime &amp; Marine (Boats &amp; Jet Skis) <a class="header-anchor" href="#_2-maritime-marine-boats-jet-skis" aria-label="Permalink to &quot;2. Maritime &amp; Marine (Boats &amp; Jet Skis)&quot;">​</a></h3><ul><li><strong>Use Case:</strong> Enforcing &quot;No-Wake Zones&quot; (<strong>&lt; 5 mph</strong>) near harbors and marinas.</li><li><strong>Application:</strong> Marine chartplotters or boat dashboard tablets ingest GPS velocity using <code>SpeedUnit.MILES_PER_HOUR</code> or <code>SpeedUnit.KILOMETERS_PER_HOUR</code> for auditory No-Wake compliance alarms.</li></ul><h3 id="_3-light-aviation-gliders" tabindex="-1">3. Light Aviation &amp; Gliders <a class="header-anchor" href="#_3-light-aviation-gliders" aria-label="Permalink to &quot;3. Light Aviation &amp; Gliders&quot;">​</a></h3><ul><li><strong>Use Case:</strong> Low-altitude gliders and ultralights monitoring maximum airspeed limits and minimum stall speeds.</li><li><strong>Application:</strong> Flight tracking tablets pipe velocity vectors into <code>TelematicsEngine</code> using <code>SpeedUnit.METERS_PER_SECOND</code> or <code>SpeedUnit.FEET_PER_SECOND</code> to provide visual corridor guidance.</li></ul>',21))])}const A=s(m,[["render",h]]);export{b as __pageData,A as default};
